-- Paket ABT "abt-relaas-penetapan-30okt" (30 Okt 2026): relaas/pemberitahuan dan penetapan PTSP blangko Derry - koma tunggal, spasi, identitas, upaya hukum pemberitahuan putusan, tanggal relaas e-Court, PA tujuan delegasi, penetapan hari sidang.
-- PRASYARAT (baca saja) "A|B|C|D": A = nomor 11200-11229 yang sudah ada tetapi isinya bukan isi paket (harus 0) | B = nomor baru yang sudah persis isi paket | C = variabel yang dirujuk paket yang ADA (harus 38) | D = variabel asal turunan (7100 7108 7109 7006 7008 9564 9565) yang isinya persis dasar paket (harus 7).
-- Benar: "0|0|38|7" (pasang pertama) atau "0|21|38|7" (pasang ulang). Selain itu berhenti, tidak ada yang diubah.
SELECT CONCAT_WS('|',
  (SELECT COUNT(*) FROM aps_badilag.abt_variabel v WHERE v.no_var BETWEEN 11200 AND 11229 AND NOT EXISTS (SELECT 1 FROM (SELECT 11200 AS n, '715bcc621768faf3aa733e2ddf6bdb94' AS h UNION ALL SELECT 11201 AS n, 'e9e4bc4014c3eee53849241b91a4591b' AS h UNION ALL SELECT 11202 AS n, 'ebd52d5b729c534a64063d6728f741ce' AS h UNION ALL SELECT 11203 AS n, '45623fb156d860dab075323e2211a6c7' AS h UNION ALL SELECT 11204 AS n, 'c3a21c1d68433ff59ae561c5b2412e99' AS h UNION ALL SELECT 11205 AS n, '8ad7b769e3c00be2873bfe93e7057647' AS h UNION ALL SELECT 11206 AS n, '1b38bc4bf6defae716a3469b424bd636' AS h UNION ALL SELECT 11207 AS n, '74a9c3f0168c3b63bfa03f14abed04d9' AS h UNION ALL SELECT 11208 AS n, '7eb5bf1594eea1f9cb4feef531b43a4a' AS h UNION ALL SELECT 11209 AS n, 'ae798ab94decb1fd6c8d820ba51de337' AS h UNION ALL SELECT 11210 AS n, 'c16e7b9e46b121d5f4b28c8c2bef96f9' AS h UNION ALL SELECT 11211 AS n, '2dca779e7cb5fbd7e7b28366cba3c0b1' AS h UNION ALL SELECT 11212 AS n, '680f5dbc927ebfb38f8b3aee639b7767' AS h UNION ALL SELECT 11213 AS n, '440ba4719bdd65b90a804ed942fbba39' AS h UNION ALL SELECT 11214 AS n, '9a70427a3c38e6f9e65c6b11ef635710' AS h UNION ALL SELECT 11215 AS n, 'c17a6a0b7c41bafa08acced3456778b8' AS h UNION ALL SELECT 11216 AS n, '99ed64cc6eafa5eef39774362c18fa88' AS h UNION ALL SELECT 11217 AS n, 'c3c081326c754ef74e6b9529d59ca380' AS h UNION ALL SELECT 11218 AS n, '8965d2ef586bbec4ffc4441e8f95a615' AS h UNION ALL SELECT 11219 AS n, '3d919013a22d837400a5a8709a7e0890' AS h UNION ALL SELECT 11220 AS n, '905adfa6070f7b796ff28f9011a7dc2b' AS h) x WHERE x.n = v.no_var AND x.h = MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), v.locked)))),
  (SELECT COUNT(*) FROM aps_badilag.abt_variabel v JOIN (SELECT 11200 AS n, '715bcc621768faf3aa733e2ddf6bdb94' AS h UNION ALL SELECT 11201 AS n, 'e9e4bc4014c3eee53849241b91a4591b' AS h UNION ALL SELECT 11202 AS n, 'ebd52d5b729c534a64063d6728f741ce' AS h UNION ALL SELECT 11203 AS n, '45623fb156d860dab075323e2211a6c7' AS h UNION ALL SELECT 11204 AS n, 'c3a21c1d68433ff59ae561c5b2412e99' AS h UNION ALL SELECT 11205 AS n, '8ad7b769e3c00be2873bfe93e7057647' AS h UNION ALL SELECT 11206 AS n, '1b38bc4bf6defae716a3469b424bd636' AS h UNION ALL SELECT 11207 AS n, '74a9c3f0168c3b63bfa03f14abed04d9' AS h UNION ALL SELECT 11208 AS n, '7eb5bf1594eea1f9cb4feef531b43a4a' AS h UNION ALL SELECT 11209 AS n, 'ae798ab94decb1fd6c8d820ba51de337' AS h UNION ALL SELECT 11210 AS n, 'c16e7b9e46b121d5f4b28c8c2bef96f9' AS h UNION ALL SELECT 11211 AS n, '2dca779e7cb5fbd7e7b28366cba3c0b1' AS h UNION ALL SELECT 11212 AS n, '680f5dbc927ebfb38f8b3aee639b7767' AS h UNION ALL SELECT 11213 AS n, '440ba4719bdd65b90a804ed942fbba39' AS h UNION ALL SELECT 11214 AS n, '9a70427a3c38e6f9e65c6b11ef635710' AS h UNION ALL SELECT 11215 AS n, 'c17a6a0b7c41bafa08acced3456778b8' AS h UNION ALL SELECT 11216 AS n, '99ed64cc6eafa5eef39774362c18fa88' AS h UNION ALL SELECT 11217 AS n, 'c3c081326c754ef74e6b9529d59ca380' AS h UNION ALL SELECT 11218 AS n, '8965d2ef586bbec4ffc4441e8f95a615' AS h UNION ALL SELECT 11219 AS n, '3d919013a22d837400a5a8709a7e0890' AS h UNION ALL SELECT 11220 AS n, '905adfa6070f7b796ff28f9011a7dc2b' AS h) x ON x.n = v.no_var AND x.h = MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), v.locked))),
  (SELECT COUNT(*) FROM aps_badilag.abt_variabel v WHERE v.no_var IN (10, 11, 20, 21, 24, 46, 47, 48, 50, 53, 98, 100, 101, 102, 103, 104, 105, 335, 336, 341, 342, 345, 346, 1033, 1035, 1036, 1064, 1069, 1099, 1176, 2224, 5369, 7017, 7051, 7153, 8808, 8809, 8811)),
  (SELECT COUNT(*) FROM aps_badilag.abt_variabel v JOIN (SELECT 7100 AS n, '20dbf3a46dc3f20e1d8fab72304ab4d6' AS h UNION ALL SELECT 7108 AS n, 'a7bbafa8207de4bd2f6dc601f79b4200' AS h UNION ALL SELECT 7109 AS n, 'e8f1a502be11aa73f712fb9655a253f6' AS h UNION ALL SELECT 7006 AS n, '6117789726bea7a0a062afad9440131f' AS h UNION ALL SELECT 7008 AS n, 'c129114cee330c7f4d2d4df129a10489' AS h UNION ALL SELECT 9564 AS n, '1d99fdc16b1c9ea1f84271fce348c166' AS h UNION ALL SELECT 9565 AS n, '91c674b01057880a97ce216e4b96c5d4' AS h) x ON x.n = v.no_var AND x.h = MD5(v.sql_query))
) AS prasyarat;
